svg.script:
var browserFrame = null;

function escapeAttribute(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function prepareBrowser(source) {
  var baseUrl = new URL('./', location.href).href;
  var html = String(source || '')
    .replace(/<meta\b[^>]*http-equiv=["']Content-Security-Policy["'][^>]*>/gi, '');
  var injection = '<base href="' + escapeAttribute(baseUrl) + '" target="_self">';
  return /<head(?:\s[^>]*)?>/i.test(html)
    ? html.replace(/<head(?:\s[^>]*)?>/i, function (head) { return head + injection; })
    : '<!doctype html><html><head>' + injection + '</head><body>' + html + '</body></html>';
}

function prepareProxyWorker() {
  if (!('serviceWorker' in navigator)) return Promise.resolve();
  var workerUrl = new URL('study/sf-sw.js', location.href).href;
  var workerScope = new URL('study/', location.href).href;
  return navigator.serviceWorker.register(workerUrl, { scope: workerScope })
    .then(function (registration) {
      var worker = registration.active || registration.waiting || registration.installing;
      if (!worker || worker.state === 'activated') return registration;
      return new Promise(function (resolve, reject) {
        worker.addEventListener('statechange', function () {
          if (worker.state === 'activated') resolve(registration);
          if (worker.state === 'redundant') reject(new Error('Browser worker installation failed'));
        });
      });
    });
}

window.addEventListener('message', function (event) {
  if (!browserFrame) return;
  if (event.source === browserFrame.contentWindow) {
    if (parent !== window) parent.postMessage(event.data, '*');
  } else if (event.source === parent && parent !== window) {
    browserFrame.contentWindow.postMessage(event.data, '*');
  }
});

window.addEventListener('load', function () {
  var host = document.getElementById('host');
  Promise.all([
    prepareProxyWorker(),
    fetch(new URL('index.html?build=browser-cdn-launch-v2', location.href).href, {
      cache: 'no-store',
      credentials: 'omit'
    }).then(function (response) {
      if (!response.ok) throw new Error('Browser response ' + response.status);
      return response.text();
    })
  ])
    .then(function (response) {
      var source = response[1];
      var frame = document.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');
      browserFrame = frame;
      frame.setAttribute('id', 'neo-browser');
      frame.setAttribute('title', 'Browser');
      frame.setAttribute('allow', 'autoplay; picture-in-picture; clipboard-read; clipboard-write; fullscreen; gamepad; microphone; camera');
      frame.setAttribute('allowfullscreen', 'true');
      frame.setAttribute('style', 'position:fixed;inset:0;width:100%;height:100%;border:0;background:#0e0e14');
      frame.setAttribute('srcdoc', prepareBrowser(source));
      host.textContent = '';
      host.appendChild(frame);
    })
    .catch(function () {
      host.textContent = 'Browser could not load. Refresh to try again.';
    });
});
